def validate_columns(columns):
    expected = {"trade_id", "price_cents", "qty"}
    if type(columns) is not dict or set(columns) != expected:
        raise ValueError("column names")
    if any(type(values) is not list for values in columns.values()):
        raise ValueError("expected lists")
    n = len(columns["trade_id"])
    if any(len(values) != n for values in columns.values()):
        raise ValueError("length mismatch")
    ids = columns["trade_id"]
    if any(type(x) is not str or not x for x in ids):
        raise ValueError("invalid ID")
    if len(set(ids)) != n:
        raise ValueError("duplicate ID")
    for name in ["price_cents", "qty"]:
        if any(type(x) is not int or x < 0 for x in columns[name]):
            raise ValueError("invalid numeric column")
    return n

columns = {"trade_id": ["T1", "T2", "T3"],
           "price_cents": [100, 200, 300], "qty": [2, 0, 3]}
print(validate_columns(columns))
selected = [i for i, qty in enumerate(columns["qty"]) if qty > 0]
result = {name: [values[i] for i in selected]
          for name, values in columns.items()}
result["notional_cents"] = [price * qty for price, qty
                            in zip(result["price_cents"], result["qty"])]
print(result["trade_id"])
print(result["notional_cents"])
print(sum(result["notional_cents"]))
